_muAdd('m4', {
  0: {emoji:"💻", subtitle:"Grade 10–12 · The studio inside your computer",
    illusText:"Tracks, timeline, mixer, plugins — a whole studio on a laptop or phone.",
    hook:{title:"Hits made in bedrooms", body:"Many South African producers made their first hits on a laptop with cracked headphones. A <strong>digital audio workstation (DAW)</strong> puts a recording studio, instruments, effects and a mixing desk inside a computer — or even a phone. Learning one opens the door to producing, film scoring and sound design."},
    intro:"A <strong>DAW</strong> records, edits, arranges and mixes audio and MIDI. Examples: FL Studio, Ableton Live, Logic Pro, GarageBand (Apple, free), Reaper (cheap), and <strong>BandLab</strong> (free, browser and mobile). Main parts: the <strong>timeline/arrangement</strong> view (tracks over time), <strong>tracks</strong> (audio tracks hold recordings; MIDI/instrument tracks hold notes that trigger virtual instruments), the <strong>piano roll</strong> (editing MIDI notes), the <strong>mixer</strong> (volume, pan, effects per track), <strong>plugins</strong> (virtual instruments and effects such as EQ, compression, reverb), the <strong>transport</strong> (play, record, loop) and the <strong>tempo</strong> setting. Projects are saved as project files; finished songs are <strong>exported</strong> (bounced) to WAV or MP3.",
    concepts:[
      {t:"green", title:"🎚️ Audio vs MIDI tracks", body:"Audio = recorded sound. MIDI = note instructions that play virtual instruments."},
      {t:"teal", title:"🎹 Piano roll", body:"Draw, move and edit notes on a grid."},
      {t:"gold", title:"🔌 Plugins", body:"Virtual instruments and effects inside the DAW."},
    ],
    examples:[
      {title:"Which track?", body:"Recording your voice with a microphone.", answer:"An <strong>audio track</strong>."},
      {title:"Which view?", body:"Drawing a melody note by note.", answer:"The <strong>piano roll</strong>."},
      {title:"Export", body:"Which format is uncompressed and best for mastering?", answer:"<strong>WAV</strong> (MP3 is compressed)."},
    ],
    mistakes:["Not saving projects regularly.","Using cracked DAWs (illegal and malware risk).","Exporting only MP3 and losing quality."],
    callout:{title:"Free options", body:"BandLab, GarageBand, Audacity and free versions of other DAWs are enough to start producing legally."},
    activity:"Open a free DAW (e.g. BandLab). Create a 4-bar loop with a drum track, a bass line and a chord track at 112 BPM. Export it as MP3.",
    activityAnswer:"Check: three tracks, tempo set to 112 BPM, a loop of 4 bars (about 8.6 seconds at 112 BPM in 4/4), exported as an MP3.",
    examTip:"Know the difference between audio and MIDI, and between WAV and MP3.",
    keyterms:[{w:"DAW",d:"Digital audio workstation"},{w:"Plugin",d:"Software instrument or effect inside a DAW"},{w:"Bounce/export",d:"Render a project to an audio file"}],
    quiz:[
      {q:"A track that records a microphone is:",opts:["MIDI","Audio","Tempo","Bus only"],a:1,et:"Real sound waves."},
      {q:"The grid for editing MIDI notes is the:",opts:["Mixer","Piano roll","Transport","Browser"],a:1,et:"Notes on a grid."},
      {q:"Uncompressed audio format:",opts:["MP3","WAV","AAC","OGG"],a:1,et:"Higher quality, bigger file."},
    ],
    conclusion:"A DAW is your studio: tracks, piano roll, mixer and plugins — save often, export WAV."},

  1: {emoji:"🎛️", subtitle:"Grade 10–12 · Getting sound in and out of the computer",
    illusText:"MIDI = instructions · audio interface = sound in/out · 44.1 kHz, 16-bit.",
    hook:{title:"The keyboard that makes no sound", body:"Plug a MIDI keyboard into a laptop and press a key — silence. The keyboard sends instructions, not sound. Load a piano plugin and suddenly it sounds like a grand piano. Load a log drum and it sounds like amapiano. Understanding <strong>MIDI</strong> and <strong>audio interfaces</strong> makes home recording make sense."},
    intro:"<strong>MIDI</strong> (Musical Instrument Digital Interface) sends performance data, not sound: which note, how hard (<strong>velocity</strong>, 0–127), when it starts and stops, and controller data (sustain pedal, knobs). It's tiny, editable and can trigger any virtual instrument. <strong>Audio</strong> is recorded sound. An <strong>audio interface</strong> converts analogue signals (microphones, guitars) to digital (<strong>ADC</strong>) and digital back to analogue for speakers/headphones (<strong>DAC</strong>). It has mic <strong>preamps</strong>, <strong>gain</strong> knobs and <strong>phantom power</strong> (+48 V) for condenser microphones. Digital audio quality: <strong>sample rate</strong> (CD quality 44.1 kHz = 44 100 samples per second) and <strong>bit depth</strong> (16-bit CD, 24-bit recording). <strong>Latency</strong> is the delay between playing and hearing.",
    concepts:[
      {t:"green", title:"🎹 MIDI", body:"Notes, velocity and timing — no sound until an instrument plays it."},
      {t:"teal", title:"🔌 Interface", body:"ADC in, DAC out, preamps, gain and phantom power."},
      {t:"gold", title:"📏 Quality", body:"Sample rate (samples per second) × bit depth (detail per sample)."},
    ],
    examples:[
      {title:"File size", body:"Uncompressed stereo audio: 44 100 Hz, 16-bit, 3 minutes.", answer:"44 100 × 16 × 2 = 1 411 200 bits/s ÷ 8 = 176 400 bytes/s × 180 s = 31 752 000 bytes ≈ <strong>30.3 MB</strong>."},
      {title:"MIDI or audio?", body:"You want to change a wrong note after recording.", answer:"Easy with <strong>MIDI</strong> — just move the note."},
      {title:"Phantom power", body:"Which microphones need it?", answer:"<strong>Condenser microphones</strong>."},
    ],
    formula:"Audio size (bytes) = sample rate × bit depth × channels × seconds ÷ 8",
    mistakes:["Expecting a MIDI keyboard to make sound on its own.","Turning gain up so high the signal clips (distorts).","Forgetting phantom power for a condenser mic."],
    callout:{title:"Phone recording", body:"Phone microphones are surprisingly good. Record in a quiet room with soft furnishings to reduce echo."},
    activity:"Calculate the uncompressed size of a 4-minute stereo song at 44.1 kHz, 16-bit. Then find the size of the same song as a 128 kbps MP3.",
    activityAnswer:"WAV: 176 400 bytes/s × 240 s = 42 336 000 bytes ≈ 40.4 MB. MP3 at 128 kbps: 128 000 ÷ 8 = 16 000 bytes/s × 240 = 3 840 000 bytes ≈ 3.7 MB.",
    examTip:"Show each step of audio file-size calculations, including dividing by 8 for bytes.",
    keyterms:[{w:"MIDI",d:"Digital performance data, not sound"},{w:"Sample rate",d:"Samples of audio per second"},{w:"Latency",d:"Delay between input and output"}],
    quiz:[
      {q:"MIDI velocity ranges from:",opts:["0–10","0–127","1–1 000","0–255"],a:1,et:"How hard a key is pressed."},
      {q:"CD-quality sample rate:",opts:["8 kHz","22 kHz","44.1 kHz","192 kHz"],a:2,et:"44 100 samples per second."},
      {q:"Phantom power is for:",opts:["Dynamic mics","Condenser mics","Speakers","MIDI cables"],a:1,et:"+48 V."},
    ],
    conclusion:"MIDI sends instructions, audio carries sound — the interface connects your gear to the computer."},

  2: {emoji:"🎚️", subtitle:"Grade 10–12 · Capturing clean sound and balancing the mix",
    illusText:"Gain staging → EQ → compression → panning → reverb → master.",
    hook:{title:"Why your recording sounds muddy", body:"You record a song at home and it sounds muddy, harsh and too quiet next to songs on Spotify. Professional tracks go through careful <strong>recording</strong>, <strong>mixing</strong> and <strong>mastering</strong>. The good news: the basics are learnable with free software."},
    intro:"<strong>Recording</strong>: a quiet room with soft surfaces; correct mic placement (about a hand's width to 20 cm for vocals, with a pop filter); <strong>gain staging</strong> — set input levels so peaks stay around −12 to −6 dBFS and never hit 0 dBFS (<strong>clipping</strong> distorts). <strong>Mixing</strong>: balance <strong>levels</strong> (volume faders), <strong>panning</strong> (left–right placement), <strong>EQ</strong> (cut muddy low-mids, cut low rumble with a high-pass filter, add clarity), <strong>compression</strong> (reduces the difference between loud and soft parts), <strong>reverb</strong> and <strong>delay</strong> (space and depth), and <strong>automation</strong> (changing settings over time). <strong>Mastering</strong> is the final polish: overall EQ, compression and limiting for loudness and consistency across playback systems. Use reference tracks and listen on several devices (headphones, phone, car).",
    concepts:[
      {t:"green", title:"📉 No clipping", body:"Peaks below 0 dBFS — record with headroom."},
      {t:"teal", title:"🎛️ EQ and compression", body:"EQ shapes tone; compression controls dynamics."},
      {t:"gold", title:"↔️ Panning", body:"Spread instruments left and right; keep bass and kick in the centre."},
    ],
    examples:[
      {title:"Fix it", body:"A vocal has a low rumble from traffic.", answer:"Use a <strong>high-pass filter</strong> (cut frequencies below about 80–100 Hz)."},
      {title:"Fix it", body:"The singer's loud and soft lines vary too much.", answer:"Use <strong>compression</strong>."},
      {title:"Panning", body:"Where should the kick drum and bass usually sit?", answer:"In the <strong>centre</strong>."},
    ],
    mistakes:["Recording too loud and clipping.","Adding too much reverb (a washed-out mix).","Mixing only on one pair of headphones."],
    callout:{title:"Take breaks", body:"Your ears tire quickly. Mix at moderate volume and rest every hour."},
    activity:"Record a short vocal or instrument in a free DAW. Set the gain without clipping, add EQ, light compression and a little reverb. Compare before and after.",
    activityAnswer:"Answers vary. The processed version should be clearer (less mud and rumble), more even in level and have a sense of space without sounding distant.",
    examTip:"Know what EQ, compression, panning and reverb each do — and one problem each solves.",
    keyterms:[{w:"Clipping",d:"Distortion when a signal exceeds the maximum level"},{w:"Compression",d:"Reducing the dynamic range of a sound"},{w:"Mastering",d:"Final processing of a mixed track"}],
    quiz:[
      {q:"Distortion from levels above 0 dBFS is:",opts:["Reverb","Clipping","Panning","Latency"],a:1,et:"Leave headroom."},
      {q:"Reduces the gap between loud and soft:",opts:["EQ","Compression","Pan","Delay"],a:1,et:"Controls dynamics."},
      {q:"A high-pass filter removes:",opts:["High frequencies","Low frequencies","All sound","Reverb"],a:1,et:"Lets highs pass, cuts lows."},
    ],
    conclusion:"Record clean, mix with purpose, master for consistency — and trust your ears."},

  3: {emoji:"🎬", subtitle:"Grade 11–12 · How music drives film, TV, games and ads",
    illusText:"Diegetic (in the scene) vs non-diegetic (soundtrack) · leitmotif · sync licensing.",
    hook:{title:"The jingle you can't forget", body:"You can probably hum the jingle of a South African fast-food chain or cellphone network right now. Music sells products, builds tension in films and makes video games exciting. Composing for media is a real career — and it pays through <strong>licensing</strong> and <strong>royalties</strong>."},
    intro:"Music in media: <strong>film and TV scores</strong>, <strong>soundtracks</strong> (licensed songs), <strong>video games</strong> (adaptive music that changes with the action), <strong>adverts and jingles</strong>, podcasts and social media. Terms: <strong>diegetic</strong> music comes from within the story world (a radio playing in the scene); <strong>non-diegetic</strong> music is the soundtrack only the audience hears. A <strong>leitmotif</strong> is a short theme linked to a character or idea. Music creates <strong>mood</strong>, builds tension, signals time and place, and links scenes. Business: <strong>sync licensing</strong> (permission to use music with pictures), <strong>royalties</strong> collected by organisations such as <strong>SAMRO</strong> in South Africa, and <strong>copyright</strong> — using music without permission can get videos removed or lead to legal action.",
    concepts:[
      {t:"green", title:"🎞️ Diegetic vs non-diegetic", body:"In the scene vs only for the audience."},
      {t:"teal", title:"🎵 Leitmotif", body:"A recurring theme for a character, place or idea."},
      {t:"gold", title:"💰 Licensing and royalties", body:"Permission and payment for using music — SAMRO collects royalties for composers."},
    ],
    examples:[
      {title:"Diegetic or not?", body:"A character turns on a car radio and a song plays.", answer:"<strong>Diegetic</strong>."},
      {title:"Diegetic or not?", body:"Tense strings play as a villain appears.", answer:"<strong>Non-diegetic</strong>."},
      {title:"Licence", body:"A brand wants a popular song in its TV ad. What does it need?", answer:"A <strong>sync licence</strong> (permission and payment)."},
    ],
    mistakes:["Thinking any music online is free to use in videos.","Confusing soundtrack and score.","Ignoring how music changes the meaning of a scene."],
    callout:{title:"Royalty-free libraries", body:"For school projects, use royalty-free or Creative Commons music and credit the creator."},
    activity:"Take a 30-second video clip. Add two different soundtracks (one happy, one tense) and describe how the meaning changes.",
    activityAnswer:"Answers vary. The same images feel playful with bright, major-key music and threatening with low, dissonant, slow music — music shapes interpretation.",
    examTip:"Use the terms diegetic, non-diegetic, leitmotif and underscore correctly.",
    keyterms:[{w:"Diegetic",d:"Music heard by characters in the story"},{w:"Leitmotif",d:"A recurring theme linked to a character or idea"},{w:"Sync licence",d:"Permission to use music with visual media"}],
    quiz:[
      {q:"Soundtrack music only the audience hears is:",opts:["Diegetic","Non-diegetic","Live","Acoustic"],a:1,et:"Outside the story world."},
      {q:"A recurring character theme is a:",opts:["Cadence","Leitmotif","Riff","Jingle"],a:1,et:"From opera and film."},
      {q:"SAMRO deals with:",opts:["Royalties for music creators","Radio licences only","Music schools","Instrument repairs"],a:0,et:"Collects and pays royalties."},
    ],
    conclusion:"Music shapes how we feel about images — and composers deserve to be licensed and paid."},

  4: {emoji:"🆓", subtitle:"Grade 10–12 · Making music with free tools",
    illusText:"BandLab: make beats on your phone. Audacity: record and edit on a PC.",
    hook:{title:"No money, no problem", body:"You don't need expensive software to start. <strong>BandLab</strong> runs free in a browser or on a phone, with loops, virtual instruments and collaboration. <strong>Audacity</strong> is free, open-source software for recording and editing audio on a computer. Many young South African creators started exactly here."},
    intro:"<strong>BandLab</strong> (free; browser, Android, iOS): multitrack studio, loops, virtual instruments, effects, and online <strong>collaboration</strong> (several people working on one project). Good for beat-making and songwriting. <strong>Audacity</strong> (free, open source; Windows, macOS, Linux): recording, cutting, trimming, fading, <strong>noise reduction</strong>, normalising, changing speed/pitch and exporting to WAV or MP3. Good for podcasts, voice-overs and editing recordings. Typical Audacity workflow: record → select and trim → noise reduction (sample the background noise, then apply) → normalise (set peak level, e.g. −1 dB) → fade in/out → export. Use headphones when recording to avoid feedback.",
    concepts:[
      {t:"green", title:"📱 BandLab", body:"Free online studio for beats, songs and collaboration."},
      {t:"teal", title:"🎙️ Audacity", body:"Free editor for recording, cleaning up and exporting audio."},
      {t:"gold", title:"🧹 Noise reduction", body:"Sample the hiss, then remove it — gently, to avoid robotic sound."},
    ],
    examples:[
      {title:"Which tool?", body:"Editing a podcast and removing background hiss.", answer:"<strong>Audacity</strong> (noise reduction)."},
      {title:"Which tool?", body:"Making a beat with friends from different towns.", answer:"<strong>BandLab</strong> (online collaboration)."},
      {title:"Order", body:"What comes first: noise reduction or normalise?", answer:"<strong>Noise reduction</strong>, then normalise."},
    ],
    mistakes:["Over-using noise reduction so the voice sounds robotic.","Recording without headphones and getting feedback.","Saving only the MP3 and losing the editable project."],
    callout:{title:"Data saving", body:"Download loops and projects on Wi-Fi; work offline where the app allows it."},
    activity:"Record a 30-second voice note in Audacity. Trim it, apply noise reduction, normalise to −1 dB, add a fade-out and export as MP3.",
    activityAnswer:"Check: silence trimmed at the start and end, hiss reduced without robotic artefacts, a peak level near −1 dB, a smooth fade-out and an MP3 file.",
    examTip:"Describe a workflow in the correct order: record → edit → clean → process → export.",
    keyterms:[{w:"Normalise",d:"Raise or lower audio so its peak reaches a set level"},{w:"Noise reduction",d:"Removing unwanted background noise"},{w:"Open source",d:"Free software whose code is public"}],
    quiz:[
      {q:"Audacity is:",opts:["Paid only","Free and open source","A microphone","A streaming service"],a:1,et:"Runs on Windows, macOS and Linux."},
      {q:"BandLab's big advantage is:",opts:["Online collaboration","It needs no internet ever","It's a piano","It prints sheet music only"],a:0,et:"Work together remotely."},
      {q:"Setting the loudest peak to −1 dB is:",opts:["Normalising","Panning","Clipping","Looping"],a:0,et:"Normalise."},
    ],
    conclusion:"Free tools are enough to create, clean up and share real music."},

  5: {emoji:"🎧", subtitle:"Grade 11–12 · From idea to finished track",
    illusText:"Idea → beat → chords → melody → record → arrange → mix → export → share.",
    hook:{title:"Your first release", body:"Today, a learner in Mthatha can make a track on a phone, upload it to streaming platforms and be heard in Brazil the same week. But a good track still needs a plan: a strong idea, a groove, chords, a melody, a clean recording, a sensible arrangement and a balanced mix. Let's put it all together."},
    intro:"Steps to <strong>record your own track</strong>: 1. <strong>Idea</strong>: genre, mood, tempo (e.g. amapiano at 112 BPM) and key. 2. <strong>Beat</strong>: drums and percussion pattern. 3. <strong>Chords</strong>: a 4- or 8-bar progression (e.g. vi–IV–I–V). 4. <strong>Bass line</strong>: chord roots or a log-drum pattern. 5. <strong>Melody/vocals</strong>: a hook that repeats. 6. <strong>Arrangement</strong>: intro, verse, chorus (hook), bridge, outro — add and remove elements for contrast. 7. <strong>Record</strong> vocals or instruments cleanly. 8. <strong>Mix</strong> (levels, EQ, compression, reverb). 9. <strong>Export</strong> (WAV master, MP3 to share). 10. <strong>Share</strong> legally: use your own or licensed samples, register your work with SAMRO, and credit collaborators.",
    concepts:[
      {t:"green", title:"🧱 Arrangement", body:"Intro → verse → chorus → verse → chorus → bridge → chorus → outro."},
      {t:"teal", title:"🪝 The hook", body:"A short, catchy idea repeated — the part people remember."},
      {t:"gold", title:"⚖️ Clear the samples", body:"Only use samples you made, bought or have permission to use."},
    ],
    examples:[
      {title:"Length", body:"A 64-bar track in 4/4 at 112 BPM. How long is it?", answer:"64 × 4 = 256 beats × (60 ÷ 112) ≈ <strong>137 seconds ≈ 2 min 17 s</strong>."},
      {title:"Contrast", body:"How can a chorus feel bigger than a verse?", answer:"<strong>Add instruments, harmonies and energy</strong>, then strip back for the verse."},
      {title:"Legal", body:"Can you use a sample from a famous song without permission?", answer:"<strong>No</strong> — you need clearance from the rights holders."},
    ],
    mistakes:["Looping 8 bars for 4 minutes with no changes.","Using uncleared samples.","Releasing without a final listen on different devices."],
    callout:{title:"Register your work", body:"Registering songs with SAMRO (and adding credits on streaming platforms) helps you get paid royalties."},
    activity:"Plan and produce a 1-minute track: choose a tempo and key, write a 4-bar progression, add drums, bass and a melody, arrange it into intro–hook–outro, mix and export.",
    activityAnswer:"Check: a clear tempo and key, at least four tracks, a hook that repeats, changes between sections, no clipping, and an exported MP3 about 1 minute long.",
    examTip:"Describe production as a sequence of steps with the purpose of each.",
    keyterms:[{w:"Hook",d:"The catchiest, most memorable part of a song"},{w:"Arrangement",d:"How sections and instruments are organised over time"},{w:"Sample clearance",d:"Permission to use part of someone else's recording"}],
    quiz:[
      {q:"The catchiest repeated part of a song is the:",opts:["Bridge","Hook","Outro","Intro"],a:1,et:"Usually in the chorus."},
      {q:"Using a famous sample needs:",opts:["Nothing","Clearance from rights holders","A louder mix","A new title"],a:1,et:"Respect copyright."},
      {q:"A master file should be exported as:",opts:["WAV","TXT","PNG","DOCX"],a:0,et:"Uncompressed quality."},
    ],
    conclusion:"Plan the idea, build the groove, arrange for contrast, mix cleanly — and release legally."},
});

